    private static IdolCard card(String id, String stageName, String fullName, String groupName,
                                 boolean isSoloist, String country, String birthDate, String role,
                                 String accentColor, String bio, String collections) {
        String pUrl = PHOTO_MAP.containsKey(id) ? PHOTO_MAP.get(id) : "";
        IdolCard c = new IdolCard(id, stageName, fullName, groupName, isSoloist, country, birthDate, role, pUrl, accentColor, bio, collections);
        if (NATIVE_MAP.containsKey(id)) {
            c.setNativeName(NATIVE_MAP.get(id));
        }
        if (!pUrl.isEmpty()) c.addPhotocard(pUrl);
        return c;
    }
